    private volatile AppLanguage _language;
    public AppLanguage Language => _language;
    public bool IsEnglish => _language == AppLanguage.English;
    public static UiText Current { get; } = new();
    public event PropertyChangedEventHandler? PropertyChanged;
    public string this[string key]
    {
        get
        {
            var entry = Entries[key];
            return _language switch
            {
                AppLanguage.English => entry.English,
                AppLanguage.Japanese => entry.Japanese,
                _ => entry.Turkish
            };
        }
    }
    public static string Get(string key) => Current[key];
    public static string Format(string key, params object[] values) => string.Format(
        System.Globalization.CultureInfo.GetCultureInfo(CultureInfoFor(Current._language)), Get(key), values);

    public static string CultureInfoFor(AppLanguage language) => language switch
    {
        AppLanguage.English => "en-US",
        AppLanguage.Japanese => "ja-JP",
        _ => "tr-TR"
    };

    // Look up translated message from Entries or preserve externally supplied errors using ErrorTranslations fallback.
    public static string LocalizeError(string message)
    {
        if (Entries.TryGetValue(message, out var entry))
        {
            return Current._language switch
            {
                AppLanguage.English => entry.English,
                AppLanguage.Japanese => entry.Japanese,
                _ => entry.Turkish
            };
        }

        return Current._language != AppLanguage.Turkish
            && ErrorTranslations.TryGetValue(message, out var translated)
                ? Current._language == AppLanguage.Japanese ? translated.Japanese : translated.English
                : message;
    }
    public void SetLanguage(AppLanguage language)
    {
        if (_language == language) return;
        _language = language;
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs("Item[]"));
    }
}

[MarkupExtensionReturnType(typeof(string))]
public sealed class LocExtension(string key) : MarkupExtension
{
    public override object ProvideValue(IServiceProvider serviceProvider) =>
        new Binding($"[{key}]") { Source = UiText.Current, Mode = BindingMode.OneWay }.ProvideValue(serviceProvider);
}
